/* DAYMARK visual direction: editorial daily route, legible training collections, same underlying actions. */
const previousDesignHome=homeApp;
function homeDayCover(){const g=goal(),day=Math.max(1,Math.min(total(g),diff(g.start,selectedDate)+1)),complete=!!g.checks[selectedDate],all=total(g);return '<section class="home-cover"><div class="home-cover-copy"><span>DAYMARK / '+(selectedDate===today()?'СЬОГОДНІ':fdate(selectedDate,true).toUpperCase())+'</span><h2>День <b>'+day+'</b><i>/ '+all+'</i></h2><p>'+esc(g.title)+'</p><button data-view="journey">'+(complete?'Моя позначка вже є':'Подивитися мій шлях')+' <b>↗</b></button></div><div class="home-cover-art" aria-hidden="true"><span class="home-cover-orbit"></span><span class="home-cover-star"><img src="assets/icon-dumbbell.svg" alt=""></span><small>ONE DAY<br>AT A TIME</small></div></section>';}
homeApp=function(){let html=previousDesignHome();const card=sportHomeCard();html=html.replace(card,'').replace('<section class="energy-card">',homeDayCover()+'<section class="energy-card">').replace('<button class="supports-entry"',card.replace(' ПРОГРАМИ',' ПРОГРАМ')+'<button class="supports-entry"');return html;};

let trainingVisible=12;
const trainingCollections=[['all','Усі',null,null],['home','Вдома','home',null],['gym','У залі','gym',null],['cardio','Кардіозона','gym','cardio'],['outdoor','Прогулянки','outdoor',null]];
actions['training-collection']=b=>{const c=trainingCollections.find(x=>x[0]===b.dataset.id);if(!c)return;trainingFilter={place:c[2]||'all',goal:c[3]||'all',gear:'all'};trainingVisible=12;render();};
actions['training-more']=()=>{trainingVisible+=12;render();};
const originalDesignFilter=actions['training-filter'];
actions['training-filter']=b=>{trainingVisible=12;originalDesignFilter(b);};
function trainingCollectionActive(c){return trainingFilter.place===(c[2]||'all')&&trainingFilter.goal===(c[3]||'all')&&trainingFilter.gear==='all';}
trainingStudio=function(){const list=TRAINING_PLANS.filter(p=>(trainingFilter.place==='all'||p.place===trainingFilter.place)&&(trainingFilter.goal==='all'||p.goal===trainingFilter.goal)&&(trainingFilter.gear==='all'||p.gear===trainingFilter.gear));return '<section class="training-studio training-studio-v2" id="trainingStudio"><div class="training-cover"><div class="training-cover-photo" role="img" aria-label="Редакційна фотографія руху"></div><div class="training-cover-copy"><span>DAYMARK TRAINING / ТВІЙ РУХ</span><h2>Тренування<br><em>під твою</em><br>ціль.</h2><p>Вдома, у залі чи надворі. Обери план і проходь вправи крок за кроком.</p><div class="training-cover-count"><b>'+TRAINING_PLANS.length+'</b><small>ПРОГРАМ<br>У БІБЛІОТЕЦІ</small></div></div><div class="training-cover-sticker">РУХ<br>ЗІ<br>МНОЮ 🏋️</div></div>'+trainingCoachPanel().replace('План, що підлаштовується.','Твій план на 7 днів.')+'<section class="training-browse"><div class="training-browse-heading"><span>ВИБЕРИ СВІЙ ФОРМАТ</span><h3>Дім, зал чи<br><em>свіже повітря?</em></h3><p>Спершу обери знайомий формат. Потім уточни мету й інвентар — не потрібно гортати всі програми.</p></div><div class="training-collections" role="group" aria-label="Колекції тренувань">'+trainingCollections.map((c,i)=>'<button data-action="training-collection" data-id="'+c[0]+'" aria-pressed="'+trainingCollectionActive(c)+'" class="'+(trainingCollectionActive(c)?'active':'')+'"><span>0'+(i+1)+'</span>'+c[1]+' <b>↗</b></button>').join('')+'</div><details class="training-refine"><summary>Уточнити фільтри <span>місце · ціль · інвентар ↗</span></summary>'+[['place','Де тренуєшся?'],['goal','Який тип?'],['gear','Що є під рукою?']].map(([key,label])=>'<div class="training-filter-group"><span>'+label.toUpperCase()+'</span><div>'+Object.entries(trainingLabels[key]).map(([id,name])=>'<button data-action="training-filter" data-kind="'+key+'" data-id="'+id+'" class="'+(trainingFilter[key]===id?'active':'')+'" aria-pressed="'+(trainingFilter[key]===id)+'">'+name+'</button>').join('')+'</div></div>').join('')+'</details><div class="training-results"><div><span>БІБЛІОТЕКА / ЗНАЙДЕНО</span><h3>'+list.length+' програм</h3></div><small>Кожну можна переглянути до старту</small></div><div class="training-grid">'+(list.length?list.slice(0,trainingVisible).map((p,i)=>'<button class="training-card '+p.tone+'" data-action="training-open" data-id="'+p.id+'"><span class="training-index">'+String(i+1).padStart(2,'0')+' / '+trainingLabels.place[p.place]+'</span><span class="training-card-art" aria-hidden="true">'+({home:'⌂',gym:'🏋️',outdoor:'↗'}[p.place])+'</span><strong>'+p.name+'</strong><small>'+p.tag+' · етапів: '+p.items.length+'</small><span class="training-card-foot"><b>'+p.minutes+' хв</b><i>Відкрити ↗</i></span></button>').join(''):'<div class="training-empty">Для такого поєднання поки немає програми. Зміни один фільтр.<button data-action="training-reset">Показати всі ↗</button></div>')+'</div>'+(list.length>trainingVisible?'<button class="training-more" data-action="training-more">Показати ще '+Math.min(12,list.length-trainingVisible)+' програм <b>↓</b></button>':'')+'</section><div class="training-principles"><b>Рух без «покарання» за їжу.</b><p>Це приклади для дорослих, а не медичне призначення. Починай із посильного навантаження; гострий біль, запаморочення чи незвичні симптоми — привід зупинитись.</p><details><summary>Як ми склали ці програми?</summary><p>Обсяг, час і частоту варто підлаштовувати поступово. За травми, вагітності чи медичних обмежень узгодь заняття з фахівцем. Анімована модель — орієнтир, не перевірка техніки.</p><p><a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">ACSM: силові тренування ↗</a> · <a href="https://odphp.health.gov/our-work/nutrition-physical-activity/physical-activity-guidelines/about-physical-activity-guidelines/questions-answers" target="_blank" rel="noopener">Рекомендації щодо руху ↗</a></p></details></div></section>';};
